#!/usr/bin/env bash
# Vendor the complete Bialet documentation into the binary.
#
# `bialet_docs` serves everything in `assets/bialet-docs/` (and the curated
# Wren references in `assets/docs/`). The manifest is generated by
# `crates/harness-tools/build.rs`, which walks these folders at build time --
# so a page copied here is embedded automatically, with no list to update.
#
# Usage:
#   bash scripts/sync-bialet-docs.sh [path/to/bialet/docs]
#
# The default source is the sibling checkout `../bialet/docs`.
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC="${1:-$REPO_ROOT/../bialet/docs}"
DST="$REPO_ROOT/assets/bialet-docs"

if [ ! -d "$SRC" ]; then
  echo "error: Bialet docs not found at $SRC" >&2
  echo "usage: $0 [path/to/bialet/docs]" >&2
  exit 1
fi

mkdir -p "$DST"

# Keep the text sources: Markdown/ReST pages and the example programs they
# include. Images, Sphinx templates and build configuration are not docs the
# agent can read.
rsync -a --delete --prune-empty-dirs \
  --include='*/' \
  --include='*.md' \
  --include='*.rst' \
  --include='*.wren' \
  --exclude='*' \
  "$SRC/" "$DST/"

pages=$(find "$DST" -type f | wc -l | tr -d ' ')
bytes=$(find "$DST" -type f -exec cat {} + | wc -c | tr -d ' ')
echo "synced $pages documentation files ($bytes bytes) from $SRC to $DST"
